#ifndef XSUITE_PACKET_H
#define XSUITE_PACKET_H
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

enum { XS_CHECKIN, XS_SOS, XS_MEDICAL, XS_HELP, XS_RTB, XS_ARRIVED, XS_ALL_CLEAR, XS_SITREP, XS_CONTACT,
       XS_WATER, XS_FOOD, XS_FUEL, XS_SUPPLIES, XS_TRANSPORT, XS_EQUIPMENT, XS_TASK_ACK, XS_TASK_DONE,
       XS_MESSAGE, XS_HAZARD, XS_ACTIONS };
const char *xsuite_action_label(uint8_t action);
// Patch slots generated by the canonical app encoders. Source identity is the radio header; 65535 is a hint only.
size_t xsuite_packet(uint8_t action, bool location, int32_t lat_e7, int32_t lon_e7, uint32_t unix_minutes,
                     uint32_t source_tag, uint32_t sequence, bool sos, char *out, size_t cap);
size_t xsuite_packet_edit(uint8_t action, bool location, int32_t lat_e7, int32_t lon_e7, uint32_t unix_minutes,
                     uint32_t source_tag, uint32_t sequence, bool sos, const char *note, uint16_t quantity,
                     uint8_t priority, char *out, size_t cap);
typedef struct { unsigned tpl, part, total; char id[33]; const char *payload; size_t payload_len; } xsuite_packet_part_t;
bool xsuite_packet_part(const char *text, xsuite_packet_part_t *part);
uint32_t xsuite_unix_minutes(uint32_t date_ddmmyy, uint32_t utc_hhmmss);
void xsuite_packet_summary(const char *text, char *out, size_t cap);
bool xsuite_packet_ack(const char *text, const char *expected_id);
#endif
